#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;

const int MAX_GRID = 15;
const int MAX_NODES = 210;

int n, T;
char grid1[MAX_GRID][MAX_GRID], grid2[MAX_GRID][MAX_GRID];
int node_index[MAX_GRID][MAX_GRID], node_count;
int zero_r, zero_c;
const int d_row[4] = {0, 0, 1, -1};
const int d_col[4] = {1, -1, 0, 0};

bool in_bounds(int r, int c) {
    return r >= 0 && c >= 0 && r < n && c < n && grid1[r][c] >= '0' && grid1[r][c] <= '9';
}

struct Edge {
    int dest, capacity, reverse;
    Edge(int d, int cap, int rev) : dest(d), capacity(cap), reverse(rev) {}
};

vector<Edge> graph[MAX_NODES * 2];
int level[MAX_NODES * 2], current[MAX_NODES * 2];

void link(int u, int v, int cap) {
    graph[u].emplace_back(v, cap, graph[v].size());
    graph[v].emplace_back(u, 0, graph[u].size() - 1);
}

void propagate(int r, int c) {
    if (grid2[r][c]) {
        link(node_index[r][c] + node_count, 2 * node_count + 1, grid2[r][c] - '0');
    }
    if (grid1[r][c] == '0') return;

    link(0, node_index[r][c], grid1[r][c] - '0');
    if (grid2[r][c]) {
        link(node_index[r][c], node_index[r][c] + node_count, 10);
    }

    int start_r = r, start_c = c;
    queue<int> q1r, q1c, q2r, q2c;
    q1r.push(r); q1c.push(c);
    q2r.push(zero_r); q2c.push(zero_c);

    vector<vector<int>> dist1(n, vector<int>(n, -1));
    vector<vector<int>> dist2(n, vector<int>(n, -1));
    dist1[r][c] = 0;
    dist2[zero_r][zero_c] = 0;

    while (!q1r.empty()) {
        int sz = q1r.size();
        for (int i = 0; i < sz; ++i) {
            int ur = q1r.front(); q1r.pop();
            int uc = q1c.front(); q1c.pop();
            if (dist2[ur][uc] >= 0) continue;
            for (int k = 0; k < 4; ++k) {
                int nr = ur + d_row[k], nc = uc + d_col[k];
                if (in_bounds(nr, nc) && dist1[nr][nc] == -1) {
                    dist1[nr][nc] = dist1[ur][uc] + 1;
                    if (dist1[nr][nc] > T) break;
                    if (dist2[nr][nc] >= 0) continue;
                    q1r.push(nr); q1c.push(nc);
                    if (grid2[nr][nc] != '0') {
                        link(node_index[start_r][start_c], node_index[nr][nc] + node_count, 10);
                    }
                }
            }
        }

        sz = q2r.size();
        for (int i = 0; i < sz; ++i) {
            int ur = q2r.front(); q2r.pop();
            int uc = q2c.front(); q2c.pop();
            for (int k = 0; k < 4; ++k) {
                int nr = ur + d_row[k], nc = uc + d_col[k];
                if (in_bounds(nr, nc) && dist2[nr][nc] == -1) {
                    dist2[nr][nc] = dist2[ur][uc] + 1;
                    q2r.push(nr); q2c.push(nc);
                }
            }
        }
    }
}

bool create_levels() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    q.push(0);
    level[0] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : graph[u]) {
            if (e.capacity > 0 && level[e.dest] == -1) {
                level[e.dest] = level[u] + 1;
                q.push(e.dest);
            }
        }
    }
    return level[2 * node_count + 1] != -1;
}

int push_flow(int u, int flow) {
    if (u == 2 * node_count + 1) return flow;
    for (int& i = current[u]; i < graph[u].size(); ++i) {
        Edge& e = graph[u][i];
        if (e.capacity > 0 && level[e.dest] == level[u] + 1) {
            int pushed = push_flow(e.dest, min(flow, e.capacity));
            if (pushed > 0) {
                e.capacity -= pushed;
                graph[e.dest][e.reverse].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int compute_flow() {
    int total = 0;
    while (create_levels()) {
        memset(current, 0, sizeof(current));
        int pushed;
        while ((pushed = push_flow(0, INT_MAX)) > 0) {
            total += pushed;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> grid1[i];
    for (int i = 0; i < n; ++i) cin >> grid2[i];

    memset(node_index, -1, sizeof(node_index));
    node_count = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid1[i][j] == 'Z') {
                zero_r = i; zero_c = j;
            } else if (in_bounds(i, j)) {
                node_index[i][j] = ++node_count;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (in_bounds(i, j)) {
                propagate(i, j);
            }
        }
    }

    cout << compute_flow() << '\n';
    return 0;
}
